--
-- Name: guest_stay; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.guest_stay AS
 SELECT r.guest_id,
    r.hotel_id,
    r.id AS reservation_id,
    COALESCE(NULLIF(TRIM(BOTH FROM g.nationality), ''::text), NULLIF(TRIM(BOTH FROM g.country), ''::text), 'UNKNOWN'::text) AS nationality,
    r.check_in_date AS check_in,
    r.check_out_date AS check_out,
    GREATEST(0, (r.check_out_date - r.check_in_date)) AS nights,
    (r.status)::text AS status,
    (COALESCE(gf.total, r.total_amount, (0)::numeric))::numeric(14,2) AS stay_revenue,
    (COALESCE(upper(TRIM(BOTH FROM g.vip_level)), 'NONE'::text) <> 'NONE'::text) AS vip_flag,
    (EXISTS ( SELECT 1
           FROM public.reservations r0
          WHERE ((r0.guest_id = r.guest_id) AND (r0.hotel_id = r.hotel_id) AND (r0.check_in_date < r.check_in_date) AND ((r0.status)::text <> 'CANCELLED'::text)))) AS is_repeat,
    (g.loyalty_tier)::text AS loyalty_tier
   FROM ((public.reservations r
     JOIN public.guests g ON ((g.id = r.guest_id)))
     LEFT JOIN public.guest_folio gf ON ((gf.reservation_id = r.id)));


--
-- Name: VIEW guest_stay; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.guest_stay IS 'Per-reservation stay row for analytics: nationality, nights, status, folio revenue, VIP, repeat (prior non-cancelled stay).';


