    CONSTRAINT provisioning_jobs_job_type_check CHECK (((job_type)::text = ANY (ARRAY[('CREATE_TENANT_SCHEMA'::character varying)::text, ('STRIPE_CUSTOMER_SYNC'::character varying)::text, ('USAGE_SNAPSHOT'::character varying)::text, ('NOTIFY_WELCOME'::character varying)::text]))),
    CONSTRAINT provisioning_jobs_status_check CHECK (((status)::text = ANY (ARRAY[('PENDING'::character varying)::text, ('RUNNING'::character varying)::text, ('DONE'::character varying)::text, ('FAILED'::character varying)::text])))
);


